package main

import (
	"bytes"
	"flag"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"sort"
	"strings"
	"testing"
)

var updateKnownEnv = flag.Bool("update-known-env", false, "rewrite known_env.go from the module's TA_* reads")

const knownEnvFile = "known_env.go"

// renderKnownEnv is known_env.go for names.
func renderKnownEnv(names []string) string {
	var b strings.Builder
	b.WriteString("// Code generated by TestKnownTAEnv_IsTheSourceList " +
		"(go test ./cmd/server -run TestKnownTAEnv -update-known-env). DO NOT EDIT.\n\n")
	b.WriteString("package main\n\n")
	b.WriteString("// knownTAEnv is every TA_* variable this module reads (env_check.go).\n")
	b.WriteString("var knownTAEnv = []string{\n")
	for _, n := range names {
		fmt.Fprintf(&b, "\t%q,\n", n)
	}
	b.WriteString("}\n")
	return b.String()
}

// The list checkTAEnv accepts is exactly the TA_* names the module's code
// reads, collected by the go/ast walk TestEnvReadmeParity uses.
func TestKnownTAEnv_IsTheSourceList(t *testing.T) {
	src, _ := collectEnvSources(t)
	var names []string
	for n := range src {
		if strings.HasPrefix(n, "TA_") {
			names = append(names, n)
		}
	}
	sort.Strings(names)
	if len(names) < 20 {
		t.Fatalf("only %d TA_* reads found: the source walk is broken", len(names))
	}
	want := renderKnownEnv(names)
	if *updateKnownEnv {
		if err := os.WriteFile(filepath.Join(".", knownEnvFile), []byte(want), 0o644); err != nil {
			t.Fatal(err)
		}
		return
	}
	got, err := os.ReadFile(knownEnvFile)
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != want {
		t.Fatalf("%s is not the list of TA_* reads; run: go test ./cmd/server -run TestKnownTAEnv -update-known-env\nwant:\n%s", knownEnvFile, want)
	}
}

func TestCheckTAEnv(t *testing.T) {
	var all []string
	for _, n := range knownTAEnv {
		all = append(all, n+"=x")
	}
	var errb bytes.Buffer
	if !checkTAEnv(append(all, "PATH=/bin", "TENANT_API_GIT_TIMEOUT=1s", "GIT_COMMITTER_NAME=x"), &errb) {
		t.Fatalf("every known variable must be accepted:\n%s", errb.String())
	}
	// Kubernetes service links of a Service named ta-x are not settings.
	for _, kv := range []string{"TA_X_SERVICE_HOST=10.0.0.1", "TA_X_SERVICE_PORT=8080",
		"TA_X_SERVICE_PORT_HTTP=8080", "TA_X_PORT=tcp://10.0.0.1:8080", "TA_X_PORT=udp://10.0.0.1:53",
		"TA_X_PORT_8080_TCP=tcp://10.0.0.1:8080", "TA_X_PORT_8080_TCP_ADDR=10.0.0.1",
		"TA_X_PORT_8080_TCP_PORT=8080", "TA_X_PORT_53_UDP_PROTO=udp"} {
		if u := unknownTAEnv([]string{kv}); len(u) != 0 {
			t.Errorf("%s refused: %v", kv, u)
		}
	}
	// Settings that only look like a port are refused: the shapes are exact,
	// and a bare _PORT passes only with the tcp:// value Kubernetes writes.
	for _, kv := range []string{"TA_LISTEN_PORT=8080", "TA_METRICS_PORT=9090", "TA_X_PORT=",
		"TA_X_PORT_HTTP=8080", "TA_X_PORT_8080=1", "TA_X_PORT_8080_TCP_HOST=x", "TA_X_SERVICE_HOSTNAME=x"} {
		name, _, _ := strings.Cut(kv, "=")
		if u := unknownTAEnv([]string{kv}); len(u) != 1 || u[0] != name {
			t.Errorf("%s accepted: %v", kv, u)
		}
	}
	errb.Reset()
	if checkTAEnv(append(all, "TA_NO_SUCH_SETTING=1", "TA_ALSO_UNKNOWN=", "TA_NO_SUCH_SETTING=2"), &errb) {
		t.Fatal("an unknown TA_* variable must be refused")
	}
	if msg := errb.String(); !strings.Contains(msg, "TA_ALSO_UNKNOWN, TA_NO_SUCH_SETTING\n") ||
		!strings.Contains(msg, "older than the Helm chart") {
		t.Errorf("message: %s", msg)
	}
}

// ADR-027 §6 / §9 item 5: every setting the ADR removed is refused at start,
// so a deployment still setting one stops instead of running as if it still
// had effect — the machine-identity audit, the switch that read the trusted
// claim headers from the environment (now from the oauth2-proxy config), and
// the switches that turned the scope axes or empty-_rbac.yaml denial off.
func TestCheckTAEnv_RefusesSettingsADR027Removed(t *testing.T) {
	for _, name := range []string{
		"TA_MACHINE_IDENTITY_AUDIT", "TA_MACHINE_IDENTITY_AUDIENCE", "TA_MACHINE_IDENTITY_ISSUER",
		"TA_IDENTITY_CLAIM_HEADERS",
		"TA_RBAC_EMPTY_OPEN", "TA_RBAC_METADATA_SCOPE_ENFORCE",
		"TA_RBAC_METADATA_WRITE_SCOPE_ENFORCE", "TA_RBAC_ORG_SCOPE_ENFORCE",
	} {
		if slices.Contains(knownTAEnv, name) {
			t.Errorf("%s is still in knownTAEnv", name)
		}
		var errb bytes.Buffer
		if checkTAEnv([]string{name + "=x"}, &errb) {
			t.Errorf("%s=x accepted; a removed setting must stop the start", name)
		} else if !strings.Contains(errb.String(), name) {
			t.Errorf("%s: the refusal does not name it:\n%s", name, errb.String())
		}
	}
}

// The subcommands refuse an unknown TA_* variable with exit 2, before doing
// anything; a known one is accepted.
func TestSubcommands_RefuseUnknownTAEnv(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "bak")
	writeFiles(t, dir, map[string]string{"_groups.yaml": "groups: {}\n"})
	run := func() (int, int, string) {
		var out, errb bytes.Buffer
		show := runStateCmd([]string{"show", "--from", dir}, strings.NewReader(""), &out, &errb)
		check := runConfigCmd([]string{"check", "--kind", "tenant-orgs", "-"}, strings.NewReader(""), &out, &errb)
		return show, check, errb.String()
	}
	t.Setenv("TA_STATE_STORE", "dir") // known
	if show, check, errOut := run(); show != 0 || check != 0 {
		t.Fatalf("known variable: show %d, check %d\n%s", show, check, errOut)
	}
	t.Setenv("TA_FROM_A_NEWER_CHART", "x")
	show, check, errOut := run()
	if show != 2 || check != 2 || strings.Count(errOut, "TA_FROM_A_NEWER_CHART") != 2 {
		t.Fatalf("unknown variable: show %d, check %d\n%s", show, check, errOut)
	}
	var errb bytes.Buffer
	if code := runStateCmd([]string{"restore", "--from", dir}, strings.NewReader(""), &bytes.Buffer{}, &errb); code != 2 ||
		!strings.Contains(errb.String(), "TA_FROM_A_NEWER_CHART") {
		t.Fatalf("restore: code %d\n%s", code, errb.String())
	}
}
